package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="regra_repasse",schema="adm_eclesial") public class RegraRepasse { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="organizacao_origem_id",nullable=false) Long organizacaoOrigemId; @Column(name="organizacao_destino_id",nullable=false) Long organizacaoDestinoId; @Enumerated(EnumType.STRING) @Column(name="tipo_base",nullable=false,length=30) TipoBaseRepasse tipoBase; @Column(precision=7,scale=4) BigDecimal percentual; @Column(name="valor_fixo",precision=15,scale=2) BigDecimal valorFixo; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) PeriodicidadeRepasse periodicidade; @Column(nullable=false) boolean ativo; @Column(name="data_inicio",nullable=false) LocalDate dataInicio; @Column(name="data_fim") LocalDate dataFim; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getOrganizacaoOrigemId(){return organizacaoOrigemId;} public Long getOrganizacaoDestinoId(){return organizacaoDestinoId;} public TipoBaseRepasse getTipoBase(){return tipoBase;} public BigDecimal getPercentual(){return percentual;} public BigDecimal getValorFixo(){return valorFixo;} public PeriodicidadeRepasse getPeriodicidade(){return periodicidade;} public boolean getAtivo(){return ativo;} public LocalDate getDataInicio(){return dataInicio;} public LocalDate getDataFim(){return dataFim;} public String getObservacao(){return observacao;} public void setOrganizacaoOrigemId(Long v){organizacaoOrigemId=v;} public void setOrganizacaoDestinoId(Long v){organizacaoDestinoId=v;} public void setTipoBase(TipoBaseRepasse v){tipoBase=v;} public void setPercentual(BigDecimal v){percentual=v;} public void setValorFixo(BigDecimal v){valorFixo=v;} public void setPeriodicidade(PeriodicidadeRepasse v){periodicidade=v;} public void setAtivo(boolean v){ativo=v;} public void setDataInicio(LocalDate v){dataInicio=v;} public void setDataFim(LocalDate v){dataFim=v;} public void setObservacao(String v){observacao=v;} }